List<String> moveRanking(List<String> order,String id,int offset){final from=order.indexOf(id);if(from<0)return [...order];final to=(from+offset).clamp(0,order.length-1),next=[...order];next.removeAt(from);next.insert(to,id);return next;}
Map<String,List<String>> setMatrixChoice(Map<String,List<String>> answer,String row,String column,{required bool multiple}){final next={for(final entry in answer.entries)entry.key:[...entry.value]};if(!multiple){next[row]=[column];return next;}final selected=next[row]??[];selected.contains(column)?selected.remove(column):selected.add(column);if(selected.isEmpty){next.remove(row);}else{next[row]=selected;}return next;}
int allocationRemaining(int total,Map<String,int> answer)=>total-answer.values.fold(0,(sum,value)=>sum+value);
bool validRanking(List<String> answer,List<String> options)=>answer.length==options.length&&answer.toSet().length==answer.length&&answer.every(options.contains);
bool validMatrix(Map<String,List<String>> answer,List<String> rows,List<String> columns,{required bool multiple,required bool required})=>answer.isNotEmpty&&(!required||answer.length==rows.length)&&answer.entries.every((entry)=>rows.contains(entry.key)&&(multiple?entry.value.isNotEmpty:entry.value.length==1)&&entry.value.toSet().length==entry.value.length&&entry.value.every(columns.contains));
bool validAllocation(Map<String,int> answer,List<String> items,int total)=>answer.length==items.length&&answer.keys.every(items.contains)&&answer.values.every((value)=>value>=0&&value<=total)&&allocationRemaining(total,answer)==0;
